from __future__ import annotations

import json
from pathlib import Path

from fastapi import APIRouter, HTTPException

from config.settings import get_settings

router = APIRouter(prefix="/api/dataset", tags=["dataset"])


@router.get("/summary")
async def get_dataset_summary():
    """Return EDA summary generated by `make eda` (eda/eda_offline.py).

    404 if data/eda_summary.json does not yet exist — run `make eda` first.
    """
    settings = get_settings()
    # Resolve relative to the project root (where the API process starts)
    summary_path = Path("data/eda_summary.json")
    if not summary_path.exists():
        raise HTTPException(
            status_code=404,
            detail="EDA summary not found — run 'make eda' to generate data/eda_summary.json.",
        )
    return json.loads(summary_path.read_text())
